\documentclass{article}
\usepackage{amsmath}
\usepackage{graphicx}
\usepackage{hyperref}

\begin{document}

\section{চল তড়িৎ (Electric Current)}

\subsection{তড়িৎ প্রবাহের একক (Unit of electric Current)}

আমরা পূর্বেই উল্লেখ করেছি, এস. আই. পন্ধিতে তড়িৎ প্রবাহ একটি মৌলিক রাশি । এ পন্ধিতে তড়িৎ প্রবাহের একক অ্যাম্পিয়ার (A) ।

মৌলিক চার্জ $e$-এর $\frac{1}{1.602176634 \times 10^{-19}}$ গুণ এক সেকেন্ড সময়ে সুযমভাবে প্রবাহিত হলে যে তড়িৎ প্রবাহ পাওয়া যায় তাকে 1 অ্যাম্পিয়ার বলে ।

\subsection{ইলেকট্রনের তাড়ন দুরতি}

\textbf{Drift Speed of Electron}

কোনো পরিবাহীর দুই প্রান্তে বিভব পার্থক্যের ফলে সৃষ্ট তড়িৎক্ষেত্র পরিবাহীর ভিতরের মুক্ত ইলেকট্রনের ওপর তাড়িত বল প্রয়োগ করে । কিন্তু এ বল ইলেকট্রনের সুষম দূরতি করতে পারে না । কারণ ইলেকট্রন গতিশীল হলে পরিবাহী যেসব অণু বা পরমাণুর সময়ে গঠিত তাদের সাথে সংযুক্ত ঘটতে থাকে, ফলে ইলেকট্রনের দুরতি কখনো তাড়িত বলে । প্রভাবে বৃদ্ধি পায় আবার কখনো সংখ্যার কারণে হ্রাস পায় । তাই ইলেকট্রন একটি ধ্রুব গড় দুরতি নিয়ে চলতে থাকে । একে ইলেকট্রনের তাড়ন দুরতি বলে । অর্থাৎ

তাড়িত বলের প্রভাবে পরিবাহীর মুক্ত ইলেকট্রন যে ধ্রুব গড় দুরতি নিয়ে চলতে থাকে তাকে ইলেকট্রনের সঞ্চারণ বা তাড়ন দুরতি বলে ।

একটি পরিবাহীর খানিকটা অংশ বিবেচনা করা যাক, যার মধ্যদিয়ে তড়িৎ প্রবাহিত হচ্ছে (চিত্র-3.3) ।

ধরা যাক,

\begin{figure}[h]
    \centering
    \includegraphics[width=0.8\textwidth]{example-image}
    \caption{চিত্র-3.3}
\end{figure}

পরিবাহীর মধ্য দিয়ে তড়িৎ প্রবাহ, $i$

পরিবাহীর বিবেচিত অংশের দৈর্ঘ্য, $l$

পরিবাহীর প্রস্থচ্ছেদের ক্ষেত্রফল, $A$

সুতরাং এ অংশের আয়তন, $Al$

\end{document}

---

রেখাগুলি এবং সূত্রগুলি নিচে দেওয়া হয়েছে:

\begin{equation}
q = nAle
\end{equation}

\begin{equation}
t = \frac{l}{v}
\end{equation}

এ সময় পরিবাহীর XY অংশের সকল মুক্ত ইলেকট্রন Y প্রান্ত অতিক্রম করবে। সূত্রাং, \( t = \frac{l}{v} \) সময়ে পরিবাহীর কোনো প্রস্থচ্ছেদের মধ্য দিয়ে অতিক্রান্ত মোট চার্জের পরিমাণ, \( q = nAle \)। সূত্রাং, তড়িৎ প্রবাহ:

\begin{equation}
i = \frac{q}{t} = \frac{nAle}{l/v} = nAev
\end{equation}

\begin{equation}
\therefore v = \frac{i}{nAe}
\end{equation}

এটি ইলেকট্রনের তাড়ন দুটির রাশিমালা।

\section{3.2.1 প্রবাহ ঘনত্ব (Current Density)}

কোনো পরিবাহীর প্রস্থচ্ছেদের একটি ক্ষেত্রফলের মধ্য দিয়ে যে তড়িৎ প্রবাহ চলে তাকে ঐ প্রবাহের প্রবাহ ঘনত্ব বলে। প্রবাহ ঘনত্বকে \( j \) দ্বারা প্রকাশ করা হয়। কোনো পরিবাহীর প্রস্থচ্ছেদের ক্ষেত্রফল \( A \) এবং কোনো সময়ে ঐ পরিবাহীতে তড়িৎ প্রবাহ \( i \) হলে ঐ সময়ে প্রবাহ ঘনত্ব-

```latex
\section{পদার্থবিজ্ঞান ছোট্টায় পত্র}

\subsection{৩.৮ নং সম্মিলিতকে প্রবাহ ঘনত্বের সাহায্যে প্রকাশ করা হলে}

\begin{equation}
j = \frac{i}{A}
\tag{৩.৫}
\end{equation}

\begin{equation}
v = \frac{i}{ne}
\tag{৩.৬}
\end{equation}

তড়িৎ প্রবাহ স্পেক্ট্রাল রাশি হলেও প্রবাহ ঘনত্ব ডেটার রাশি। পরিবাহীর অতিক্ষুদ্র $d\vec{A}$ ক্ষেত্রফলের মধ্য দিয়ে প্রবাহ ঘনত্ব $\vec{j}$ হলে তড়িৎ প্রবাহ-

\begin{equation}
i = \int \vec{j} \cdot d\vec{A}
\tag{৩.৭}
\end{equation}

প্রবাহ ঘনত্বের একক $A \cdot m^{-2}$

\section*{গণিতিক উদাহরণ}

\textbf{উদাহরণ-৩.১:} কোনো পরিবাহীর মধ্য দিয়ে 20 টি ইলেকট্রন কভ সময়ের মধ্যে প্রবাহিত হলে 2 mA তড়িৎ প্রবাহ পাওয়া যায়? আমরা জানি, তড়িৎ প্রবাহ,

\begin{equation}
i = \frac{q}{t}
\end{equation}

\begin{equation}
\therefore t = \frac{q}{i}
\end{equation}

\begin{equation}
= \frac{20 \times 1.6 \times 10^{-19} \text{ C}}{2 \times 10^{-3} \text{ A}}
\end{equation}

\begin{equation}
= 1.6 \times 10^{-15} \text{ s}
\end{equation}

\textbf{উদাহরণ-৩.২:} একটি তারের ব্যাস 1.8 mm। এর মধ্য দিয়ে 1.3 A সূচম তড়িৎ প্রবাহ চলছে। তারের প্রতি ঘনমিটারের পরিবাহন ইলেকট্রনের সংখ্যা 8.49 $\times$ 10$^{24}$ হলে ইলেকট্রনের তাঁতন দূরি নির্ণয় করো। আমরা পাই, তারের প্রস্থচ্ছেদের ক্ষেত্রফল,

\begin{equation}
A = \frac{1}{4} \pi d^{2}
\end{equation}

\begin{equation}
= \frac{1}{4} (3.14) (0.0018 \text{ m})^{2}
\end{equation}

\begin{equation}
= 2.54 \times 10^{-6} \text{ m}^{2}
\end{equation}

আবার, ইলেকট্রনের তাঁতন দূরি,

\begin{equation}
v_{d} = \frac{i}{nAe}
\end{equation}

\begin{equation}
= \frac{1.3 \text{ A}}{(8.49 \times 10^{24} \text{ m}^{-3}) (2.54 \times 10^{-6} \text{ m}^{2}) (1.6 \times 10^{-19} \text{ C})}
\end{equation}

\begin{equation}
= 0.377 \text{ m} \cdot \text{s}^{-1}
\end{equation}

\textbf{উদাহরণ-৩.৩:} একটি বৃত্তাকার তারের ব্যাস 1 mm। এর মধ্য দিয়ে 1 ঘন্টা 15 মিনিটে 90 C চার্জ প্রবাহিত হচ্ছে। প্রবাহ ঘনত্ব নির্ণয় করো। আমরা জানি, প্রবাহ ঘনত্ব-

\begin{equation}
j = \frac{i}{A}
\end{equation}

\begin{equation}
= \frac{q}{\pi r^{2} t}
\end{equation}

\begin{equation}
= \frac{90 \text{ C}}{\pi \times (0.5 \times 10^{-3} \text{ m})^{2} \times 4500 \text{ s}}
\end{equation}

\begin{equation}
= 25464.79 \text{ A} \cdot \text{m}^{-2}
\end{equation}
