\begin{document}

\section{পদার্থবিজ্ঞান দ্বিতীয় পত্র}

\subsection{একক : এস. আই. পদ্ধতিতে রোধের একক ও'ম। একে Ω (গ্রিক বর্ণমালা বড় হাতের ওমেগা) এর সাহায্যে সূচিত করা হয়। কোনো পরিবাহীর দু'প্রান্তের বিভব পার্থক্য 1 V রাখা হলে যদি এর মধ্য দিয়ে 1 A তড়িৎ প্রবাহ চলে তবে ঐ পরিবাহীর রোধকে এক ও'ম (Ω) বলে। অর্থাৎ
\begin{equation}
1 \, \Omega = \frac{1 \, \text{V}}{1 \, \text{A}} = 1 \, \text{V}\cdot\text{A}^{-1}
\end{equation}

\subsection{পরিবাহিতা (Conductance)}

\subsubsection{(3.8) নং সমীকরণ থেকে দেখা যায়, পরিবাহিতা-}

\begin{equation}
G = \frac{i}{V}
\tag{3.11}
\end{equation}

সূত্রাং, কোনো পরিবাহীর মধ্যে তড়িৎ প্রবাহ ও এর দু'প্রান্তের বিভব পার্থক্যের অনুপাতকে ঐ পরিবাহীর পরিবাহিতা বলে।
একক : পরিবাহিতার এস আই একক সিমেস (S)। কোনো পরিবাহীর দু'প্রান্তের বিভব পার্থক্য 1 V রাখা হলে যদি এর মধ্য দিয়ে 1 A তড়িৎ প্রবাহ চলে তবে ঐ পরিবাহীর পরিবাহিতাকে এক সিমেস বলে।
\begin{equation}
1 \, \text{S} = \frac{1 \, \text{A}}{1 \, \text{V}} = 1 \, \text{A}\cdot\text{V}^{-1} = 1 \, \text{Ω}^{-1}
\end{equation}

পরিবাহিতা নির্ভর করে পরিবাহীর দৈর্ঘ্য, প্রস্থেছেদের ক্ষেত্রফল, উপাদান ও তাপমাত্রার উপর। সাধারণভাবে সকল ধাতুই ভালো পরিবাহী অর্থাৎ এদের পরিবাহিতা বেশি। কারণ অধাতু হলেও ভালো পরিবাহী। আবার সিলিকন, জামেনিয়াম ইত্যাদি সামন্য পরিবাহী। এদেরকে অর্ধপরিবাহী বলে। কাচ, প্লাস্টিক, রাবার, ইবোনাইট ইত্যাদির পরিবাহিতা খুব কম, নেই বললেই চলে। এদেরকে অপরিবাহী বা অন্তরক বলে।

