\section{পদার্থবিজ্ঞান দ্বিতীয় পত্র}

\subsection{গণিতিক উদাহরণ}

\textbf{উদাহরণ-৩.২৪:} একটি কোয়েরের তড়িচ্চালক বল 1.5 V এবং অভ্যন্তরীণ রোধ 2 Ω। এর প্রত্যন্ধ 10 Ω রোধের তার দ্বারা যুক্ত করলে কত বিদ্যুৎ প্রবাহিত হবে বের করো।

আমরা জানি, তড়িৎ প্রবাহ,

\begin{equation}
i = \frac{E}{R + r}
\end{equation}

\begin{equation}
= \frac{1.5 \, \text{V}}{10 \, \Omega + 2 \, \Omega} = 0.125 \, \text{A}
\end{equation}

\textbf{উদাহরণ-৩.২৫:} একটি কোয়েরের তড়িচ্চালক বল 2 V। এতে যখন 5 A তড়িৎ প্রবাহিত হয়, তখন এর বিভব পার্থক্য 1.8 V হয়। কোয়েরের অভ্যন্তরীণ রোধ কত?

আমরা জানি,

\begin{equation}
E = V + V'
\end{equation}

সূত্রাং যারানো বিভব,

\begin{equation}
V' = E - V = 2 \, \text{V} - 1.8 \, \text{V} = 0.2 \, \text{V}
\end{equation}

আবার, যারানো বিভব,

\begin{equation}
V' = r \, i \quad \therefore r = \frac{V'}{i} = \frac{0.2 \, \text{V}}{5 \, \text{A}} = 0.04 \, \Omega
\end{equation}

\textbf{উদাহরণ-৩.২৬:} 4 Ω ও 6 Ω এর দুটি রোধকে শ্রেণি সংযোগে যুক্ত করে সংযোগটিকে 2.2 V তড়িচ্চালক বল এবং 1 Ω অভ্যন্তরীণ রোধের একটি কোয়েরের সাথে যুক্ত করে বর্তনী পূর্ণ করা হলো। প্রতিটি রোধকের প্রাথমিক বিভব পার্থক্য নির্ণয় করো।

আমরা জানি, শ্রেণি সংযোগে তুলু রোধ,

\begin{equation}
R_S = R_1 + R_2 = 4 \, \Omega + 6 \, \Omega = 10 \, \Omega
\end{equation}

তড়িৎ প্রবাহ,

\begin{equation}
i = \frac{E}{R + r} = \frac{2.2 \, \text{V}}{10 \, \Omega + 1 \, \Omega} = 0.2 \, \text{A}
\end{equation}

$R_1$ রোধের প্রাথমিক বিভব পার্থক্য,

\begin{equation}
V_1 = R_1 \, i = (4 \, \Omega)(0.2 \, \text{A}) = 0.8 \, \text{V}
\end{equation}

$R_2$ রোধের প্রাথমিক বিভব পার্থক্য,

\begin{equation}
V_2 = R_2 \, i = (6 \, \Omega)(0.2 \, \text{A}) = 1.2 \, \text{V}
\end{equation}

\textbf{উদাহরণ-৩.২৭:} 4 Ω ও 12 Ω রোধবিশিষ্ট দুটি তারকে সমান্তরাল সংযোগ করে 4 V তড়িচ্চালক শক্তিবিশিষ্ট একটি কোয়েরের সাথে যুক্ত করা হলো। কোয়েরের অভ্যন্তরীণ রোধ 1 Ω। প্রত্যেক তারকের মধ্য দিয়ে কি পরিমাণ তড়িৎ প্রবাহ হবে?

আমরা জানি, সমান্তরাল সংযোগে তুলু রোধ $R_P$ হলো-

\begin{equation}
\frac{1}{R_P} = \frac{1}{R_1} + \frac{1}{R_2} = \frac{1}{4 \, \Omega} + \frac{1}{12 \, \Omega} = \frac{3 + 1}{12 \, \Omega} = \frac{4}{12 \, \Omega} = \frac{1}{3 \, \Omega}
\end{equation}

\begin{equation}
\therefore R_P = 3 \, \Omega
\end{equation}

তড়িৎ প্রবাহ-

\begin{equation}
i = \frac{E}{R + r} = \frac{4 \, \text{V}}{3 \, \Omega + 1 \, \Omega} = 1 \, \text{A}
\end{equation}

সংযোগের দুই প্রত্যেকের বিভব,

\begin{equation}
V = R_P \, i = (3 \, \Omega)(1 \, \text{A}) = 3 \, \text{V}
\end{equation}

সূত্রাং, $R_1$ রোধের মধ্য দিয়ে তড়িৎ প্রবাহ,

\begin{equation}
i_1 = \frac{V}{R_1} = \frac{3 \, \text{V}}{4 \, \Omega} = 0.75 \, \text{A}
\end{equation}

এবং $R_2$ রোধের মধ্য দিয়ে তড়িৎ প্রবাহ, $i_2 = \frac{V}{R_2} = \frac{3 \, \text{V}}{12 \, \Omega} = 0.25 \, \text{A}$

