\section{পদার্থবিজ্ঞান দ্বিতীয় পত্র}

\subsection{উদাহরণ-৩.৪৮: একটি মিটার ব্রিজের তারের দৈর্ঘ্য 1 m। এর বামদিকে 60 Ω এর একটি প্রমাণ রোধ এবং ডান দিকে একটি অজানা রোধ স্থাপন করায় তারের বাম প্রান্ত হতে 0.48 m দূরে সাম্যবিন্দু পাওয়া গেল। অজানা রোধটি নির্ণয় করুন।}

\begin{equation}
\frac{R_{1}}{R_{2}} = \frac{l}{(100-l)}
\end{equation}
\begin{equation}
\therefore R_{2} = R_{1} \times \frac{100-l}{l} = 60 \Omega \times \frac{100-48}{48} = 65 \Omega
\end{equation}

\subsection{উদাহরণ-৩.৪৫: কোনো মিটার ব্রিজের বাম ফাঁকে 2 Ω এবং ডান ফাঁকে 3 Ω রোধ যুক্ত করা হলে নিঃস্পন্দ বিন্দু কোথায় পাওয়া যাবে? নিঃস্পন্দ তারের ঠিক মধ্যস্থলে পেতে যায় 3 Ω রোধের সাথে কত রোধ সমান্তরাল সংযোগে যুক্ত করতে হবে?}

\subsection{প্রথম ক্ষেত্রে,}

\begin{equation}
\frac{R_{1}}{R_{2}} = \frac{l}{(100-l)}
\end{equation}
\begin{equation}
\text{বা, } \frac{2}{3} = \frac{l}{100-l}
\end{equation}
\begin{equation}
\text{বা, } 3l = 200 - 2l
\end{equation}
\begin{equation}
\text{বা, } 5l = 200
\end{equation}
\begin{equation}
\therefore \ l = 40 \text{ cm}
\end{equation}

\subsection{দ্বিতীয় ক্ষেত্রে,}

\begin{equation}
\frac{R_{1}}{R_{2}} = \frac{l}{(100-l)}
\end{equation}
\begin{equation}
\text{বা, } R_{2} = \frac{100-l}{l} \times R_{1} = \frac{100-50}{50} \times 2 \Omega = 2 \Omega
\end{equation}

\subsection{ধরা যাক, 3 Ω এর সাথে S_{1} রোধ সমান্তরালে যুক্ত করতে হবে। সুতরাং}

\begin{equation}
\frac{1}{2} = \frac{1}{3} + \frac{1}{S_{1}}
\end{equation}
\begin{equation}
\text{বা, } \frac{1}{S_{1}} = \frac{1}{2} - \frac{1}{3} = \frac{1}{6}
\end{equation}
\begin{equation}
\therefore \ S_{1} = 6 \Omega
\end{equation}

\subsection{বাড়ির কাজ}

\begin{itemize}
    \item নাজিমুল পদার্থবিজ্ঞান ব্যবস্থারিক ক্লাসে মিটার ব্রিজের সাহায্যে অজ্ঞাত তারের আপেক্ষিক রোধ নির্ণয়ের জন্য যত্রের বাম ফাঁকে 200 cm দৈর্ঘ্য এবং 0.12 mm বাস্তবে অজ্ঞাত তার স্থাপন করে যত্রের ডান ফাঁকে রোধ বাক্স রেখে বন্ধ করলে সংযুক্ত প্যালাভানোমিটারে বিক্ষেপ দেয়। বন্ধনীর সাথে পরে সে যত্রের বাম প্রান্ত থেকে 37.5 cm দূরে নিঃস্পন্দ বিন্দু নির্ধারণ করলে।
    \item ক, অজ্ঞাত তারটির রোধ কত?
    \item খ, ব্যবহৃত তারটির পরিবর্তে একই আকার ও আকৃতির ডিসি একটি তার ব্যবহার করলে যদি যত্রের বাম প্রান্ত থেকে 45 cm দূরে নিঃস্পন্দ বিন্দু সৃষ্টি হয় তবে কোন তারের পরিবাহকত্ব নেশি? গণিতিক বিশ্লেষণ করো।
\end{itemize}

