\section{উদাহরণ-৫. সমন্তরালভাবে সংযুক্ত দুটি তারের প্রান্তে 3 V তড়িচ্ছালক বল এবং 0.5 Ω অভ্যন্তরীণ রোধের একটি কোষ লাগানো হলো। তার দুটির রোধ 2 Ω ও 5 Ω হলে এতে প্রতি সেকেন্ডে উৎপন্ন তাপের অনুপাত নির্ণয় করো। রোধদ্বয় সমন্তরালে যুক্ত হওয়ায় উভয়ের দুই প্রান্তের বিভব পার্থক্য \( V \) সমান হবে। আমরা পাই, প্রথম ও দ্বিতীয় তারের উৎপন্ন তাপ যথাক্রমে-
\begin{equation}
H_{1} = \frac{V^{2}t}{R_{1}} \text{ ও } H_{2} = \frac{V^{2}t}{R_{2}}
\end{equation}
সূতরাং
\begin{equation}
\frac{H_{1}}{H_{2}} = \frac{\frac{V^{2}t}{R_{1}}}{\frac{V^{2}t}{R_{2}}} = \frac{R_{2}}{R_{1}} = \frac{5}{2}
\end{equation}
\begin{equation}
\therefore H_{1} : H_{2} = 5 : 2
\end{equation}

\section{উদাহরণ-৬. একটি কোষের বিদ্যুচ্ছালক বল 14 V এবং অভ্যন্তরীণ রোধ 2 Ω। 20 Ω ও 30 Ω রোধের দুটি তারকে সমন্তরালে সাজিয়ে 70 Ω রোধের একটি তারের সাথে শ্রেণিতে যুক্ত করলে রোধের এই সংযোগকে কোষের দুই প্রান্তের সাথে যুক্ত করলে প্রতিটি রোধের মধ্য দিয়ে কী পরিমাণ তড়িৎ প্রবাহিত হবে? কোষের প্রাত্যুষ বিভব পার্থক্য নির্ণয় করো।}

20 Ω ও 30 Ω রোধদ্বয় সমন্তরালে যুক্ত। এদের তুল্য রোধ \( R_{P} \) হলে-
\begin{equation}
\frac{1}{R_{P}} = \frac{1}{20 \, \Omega} + \frac{1}{30 \, \Omega} = \frac{3 + 2}{60 \, \Omega} = \frac{5}{60 \, \Omega} = \frac{1}{12 \, \Omega}
\end{equation}
\begin{equation}
\therefore R_{P} = 12 \, \Omega
\end{equation}

\( R_{P} \) ও 70 Ω এর শ্রেণি সংযোগে তুল্য রোধ,
\begin{equation}
R_{S} = R_{P} + 70 \, \Omega = 12 \, \Omega + 70 \, \Omega = 82 \, \Omega
\end{equation}

